{
  "window_id": "w0003",
  "observed_failures": [
    {
      "filename": "034.jpg",
      "field": "date",
      "predicted": "2018-08-09",
      "failure_mode": "wrong_date_value",
      "notes": "Receipt header shows 'Date: 09/03/2018' but prediction returned 2018-08-09. Either OCR misread '03' as '08', or extractor picked a different date-like token on the page. Day/month vs month/day ambiguity suspected (DD/MM/YYYY vs MM/DD/YYYY)."
    },
    {
      "filename": "074.jpg",
      "field": "total_amount",
      "predicted": "702.00",
      "failure_mode": "ocr_digit_corruption_not_handled",
      "notes": "Trajectory already observed OCR rendering the total as 'Total inel. of GBT 702.00' where real value is 102.00 (leading '1' misread as '7'). Keyword match found but no sanity cross-check against Subtotal / Payment / Total Amt Rounded (all 102.00)."
    },
    {
      "filename": "077.jpg",
      "field": "total_amount",
      "predicted": "23.26",
      "failure_mode": "picked_pre_rounding_total",
      "notes": "Receipt contains 'Total (Inclusive of GST): 23.26', 'Rounding Adj: -0.01', 'TOTAL: 23.25'. Extractor returned the pre-rounding line. Oracle likely uses the final post-rounding TOTAL."
    },
    {
      "filename": "078.jpg",
      "field": "total_amount",
      "predicted": "",
      "failure_mode": "extraction_returned_empty_string_instead_of_value_or_null",
      "notes": "Receipt has 'Total : 92.80' and 'Grand Total : 92.80'. Extraction failed AND produced an empty string in the cell rather than real null. Two bugs: keyword match missed Grand Total (likely spacing/line-split), and the writer emitted '' instead of None."
    }
  ],
  "root_causes": [
    {
      "id": "rc_null_representation",
      "summary": "On extraction failure the agent wrote '' instead of Python None, which is both a schema violation and masks real missingness. The original image-ocr/xlsx skills never specify how to serialize missing fields."
    },
    {
      "id": "rc_keyword_priority_underspecified",
      "summary": "Original image-ocr skill contains no guidance for priority-tiered keyword extraction with exclusion rules (GRAND TOTAL > TOTAL RM > TOTAL AMOUNT > TOTAL/AMOUNT, excluding SUB TOTAL / tax / discount / change). Agent had to reinvent this from scratch under a 65-turn budget and ran out of iterations with edge cases unresolved."
    },
    {
      "id": "rc_post_rounding_vs_pre_rounding",
      "summary": "No rule to prefer post-rounding/final TOTAL lines over 'Inclusive of GST' / 'Net Total' lines when both exist. Receipts often print both; the oracle uses the final cash-equivalent figure."
    },
    {
      "id": "rc_ocr_digit_noise_unmitigated",
      "summary": "No guidance to (a) run multi-pass OCR / preprocessing variants and vote, or (b) sanity-check extracted totals against neighboring Subtotal / Payment / Cash lines to catch single-digit OCR corruptions (e.g. 102.00 misread as 702.00)."
    },
    {
      "id": "rc_date_format_ambiguity",
      "summary": "Original skill lacks explicit rules for DD/MM/YYYY vs MM/DD/YYYY disambiguation on Malaysian receipts and for choosing the correct date when multiple date-like tokens appear (header 'Date:' line vs transaction ID containing date digits)."
    },
    {
      "id": "rc_xlsx_strict_schema_not_documented",
      "summary": "Original xlsx skill emphasizes financial-model color/formula conventions but does not describe strict-schema outputs (exact sheet name 'results', three exact columns, no index, real nulls, string amounts with two decimals) — exactly the contract this grader checks."
    },
    {
      "id": "rc_no_pipeline_scaffold_for_receipt_batch",
      "summary": "Neither skill ties together: sorted filename iteration + per-image try/except + structured field dict + null-safe row + strict-schema xlsx write. Agent spent most of its 65 iterations re-deriving this scaffold instead of refining extraction."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "No section on structured field extraction (dates, monetary totals) from noisy receipt text."
    },
    {
      "skill": "image-ocr",
      "defect": "No priority/exclusion keyword framework; no two-line fallback when amount is on the next row; no guidance on preferring post-rounding/final TOTAL."
    },
    {
      "skill": "image-ocr",
      "defect": "No null-safety contract: must return None on failure, never '', 'nan', or a swallowed exception."
    },
    {
      "skill": "image-ocr",
      "defect": "Multi-pass OCR example exists but is not wired to a 'vote / sanity check against siblings' pattern that would catch single-digit corruptions."
    },
    {
      "skill": "image-ocr",
      "defect": "Date extraction / ISO normalization is not covered. No rule for DD/MM/YYYY-first interpretation in receipt contexts, no rule for choosing the Date: header vs incidental date-shaped tokens."
    },
    {
      "skill": "xlsx",
      "defect": "No 'strict-schema output' section: exact sheet name, exact columns, no extra sheets/index, lexicographic filename ordering, two-decimal strings for money, real nulls for missing cells."
    },
    {
      "skill": "xlsx",
      "defect": "Guidance currently pushes formulas and model formatting; silent on literal-value extraction outputs where every drift fails line-by-line grading."
    },
    {
      "skill": "xlsx",
      "defect": "No re-read verification pattern (reopen and assert sheet name, columns, dtypes, row order) to catch common mistakes before returning."
    },
    {
      "skill": "openai-vision",
      "defect": "Referenced as an OCR alternative but not integrated with the structured-receipt pipeline; no guidance on when to escalate from Tesseract to vision OCR for hard receipts."
    },
    {
      "skill": "pdf",
      "defect": "Unrelated to this task; no defect material to repair for this evidence window, but no cross-link from receipt/image workflows to pdf when a receipt is actually a PDF scan."
    },
    {
      "skill": "video-frame-extraction",
      "defect": "Unrelated to this task; no defect material to repair for this evidence window."
    }
  ],
  "repair_recommendations": [
    {
      "skill": "image-ocr",
      "change": "Add a 'Structured Field Extraction (Receipts/Forms)' section specifying: (a) tiered keyword priority GRAND TOTAL > TOTAL RM/TOTAL:RM > TOTAL AMOUNT > {TOTAL DUE, AMOUNT DUE, BALANCE DUE, NETT TOTAL, NET TOTAL, TOTAL, AMOUNT}; (b) exclusion keywords checked BEFORE priority match (SUBTOTAL/SUB TOTAL, TAX, GST, SST, DISCOUNT, CHANGE, CASH TENDERED), with note that 'Incl GST' on a TOTAL line is NOT an exclusion; (c) two-line fallback for amount on the following line; (d) tie-breaker: when multiple same-priority matches exist, prefer the one that appears AFTER a 'Rounding' / 'Round Adj' line (post-rounding) over the pre-rounding one."
    },
    {
      "skill": "image-ocr",
      "change": "Add a 'Date Extraction and ISO Normalization' section: regex set for DD/MM/YYYY, DD-MM-YYYY, DD/MM/YY, YYYY-MM-DD, DD-MMM-YYYY; default day-first interpretation for receipt contexts; prefer dates on a line beginning with 'Date', 'Tarikh', or near 'Time'; ignore date-shaped tokens embedded in invoice/slip IDs; return None rather than guess under ambiguity."
    },
    {
      "skill": "image-ocr",
      "change": "Add a 'Null-Safe Per-Image Pipeline' pattern: wrap each file in try/except, return {'date': None, 'total_amount': None} on any failure, never '' or 'nan'; always emit one output row per input even if both fields are None."
    },
    {
      "skill": "image-ocr",
      "change": "Add a 'Digit Sanity Check' rule: after extracting the candidate total, compare against any Subtotal / Payment / Cash / Total Rounded values on the same receipt; if the candidate differs from a strong majority by exactly one leading digit, re-run OCR with a preprocessing variant (upscale 2x, threshold, invert) on the keyword line's bounding region and vote."
    },
    {
      "skill": "image-ocr",
      "change": "Add a short 'Escalation to openai-vision' note: when Tesseract confidence is low or the keyword/number regex finds nothing after multi-pass OCR, defer the single image to the openai-vision skill with a structured-JSON prompt for {date, total_amount}."
    },
    {
      "skill": "xlsx",
      "change": "Add a 'Strict-Schema Outputs (graded line-by-line)' section with an explicit checklist: exact file path, exactly one sheet with the exact requested name (case preserved), exact columns in exact order, no index, no helper/debug columns, no extra sheets, deterministic lexicographic row order, string-typed amounts with exactly two decimals, real None for missing cells."
    },
    {
      "skill": "xlsx",
      "change": "Add a canonical pandas-based write pattern using ExcelWriter(engine='openpyxl'), to_excel(sheet_name=..., index=False), with df[col].astype('object') to preserve string nulls and prevent float coercion of amounts; plus a mandatory re-read verification snippet that asserts sheet set, column list, row ordering, and that non-null amounts match r'^\\d+\\.\\d{2}$'."
    },
    {
      "skill": "xlsx",
      "change": "Document pitfalls that break line-by-line grading: writing floats instead of two-decimal strings; leaving NaN instead of None; default 'Sheet1' creation; forgetting index=False; non-lexicographic row order; currency prefixes or thousand separators retained in the cell; extra success/confidence/raw_text columns."
    },
    {
      "skill": "xlsx",
      "change": "Clarify that the financial-model color/formula/recalc guidance applies to analytical workbooks only, and does NOT apply to strict-schema extraction outputs (which should be literal values, no formulas, no styling)."
    },
    {
      "skill": "openai-vision",
      "change": "Add a short 'Receipt Field Extraction' recipe: prompt the model to return strict JSON {date: 'YYYY-MM-DD'|null, total_amount: 'N.NN'|null} with the same priority/exclusion rules as image-ocr, and document that this skill is the fallback invoked by image-ocr when Tesseract fails."
    }
  ],
  "confidence": {
    "overall": 0.78,
    "observed_failures": 0.9,
    "root_causes": 0.8,
    "skill_defects": 0.8,
    "repair_recommendations": 0.75,
    "notes": "Failure attributions for 034/074/077/078 are grounded in the recorded trajectory text and the per-field feedback; the exact oracle values are not consulted. Rounding-preference and digit-sanity recommendations are inferred from visible OCR lines and may not fully capture the oracle's tie-breaking rule."
  }
}
